    fn pixels(jpeg: &[u8], dict: &[u8]) -> Vec<u8> {
        let params = ImageDecodeParams {
            width: 16,
            height: 16,
            num_components: Some(3),
            ..Default::default()
        };
        let decoded = decode(jpeg, &Dict::from_bytes(dict).unwrap(), &params).unwrap();
        assert_eq!(decoded.data.len(), 16 * 16 * 3);
        decoded.data.into_owned()
    }

    fn near(pixel: &[u8], want: [u8; 3]) -> bool {
        pixel.iter().zip(want).all(|(a, b)| a.abs_diff(b) <= 16)
    }

    /// PdfCraft #7852: zune-jpeg 0.5.15 decodes a frame with one scan per component into
    /// coloured stripes; each half keeps its colour.
    #[test]
    fn a_baseline_frame_with_one_scan_per_component_keeps_its_colours() {
        assert_eq!(craft_jpeg::split_scan_components(&NON_INTERLEAVED), Some(3));
        assert_eq!(craft_jpeg::split_scan_components(&INTERLEAVED), None);
        for jpeg in [&NON_INTERLEAVED[..], &INTERLEAVED[..]] {
            let px = pixels(jpeg, b"<< >>");
            for y in [1, 8, 14] {
                let at = |x: usize| &px[(y * 16 + x) * 3..][..3];
                assert!(
                    near(at(2), [0xe0, 0x40, 0x20]),
                    "left at row {y}: {:?}",
                    at(2)
                );
                assert!(
                    near(at(13), [0x20, 0x60, 0xc0]),
                    "right at row {y}: {:?}",
                    at(13)
                );
            }
        }
    }

    /// `/ColorTransform 0` leaves the samples as stored (YCbCr here), with either decoder.
    #[test]
    fn color_transform_0_keeps_the_stored_samples_for_one_scan_per_component() {
        let stored = pixels(&NON_INTERLEAVED, b"<< /ColorTransform 0 >>");
        let left = &stored[(8 * 16 + 2) * 3..][..3];
        assert!(!near(left, [0xe0, 0x40, 0x20]), "{left:?}");
        // As zune-jpeg leaves them; the two decoders' rounding may differ by a step.
        let zune = pixels(&INTERLEAVED, b"<< /ColorTransform 0 >>");
        assert!(
            stored.iter().zip(&zune).all(|(a, b)| a.abs_diff(*b) <= 2),
            "{stored:?} {zune:?}"
        );
    }
